style.css:
@-moz-document url-prefix("https://www.kobo.com") {
/* Base Background and Text */
    body, 
    html, 
    .main-content, 
    .rich-header,
    .rich-header-slim,
    a.button,
    ul,
    button,
    header,
    div,
    .text-black,
    .bg-white,
    #body-container {
        background-color: #121212 !important;
        background: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* Headers and Navigation */
    header, 
    .header-container, 
    .top-navigation, 
    .secondary-nav,
    .search-bar-container {
        background-color: #1a1a1a !important;
        border-bottom: 1px solid #333 !important;
    }

    /* Cards and Containers */
    .book-card, 
    .item-wrapper, 
    .billing-address-container, 
    .payment-method-container,
    .promo-banner,
    .kobo-card {
        background-color: #1e1e1e !important;
        border: 1px solid #333 !important;
        box-shadow: 0 4px 6px rgba(0,0,0,0.3) !important;
    }

    /* Text Colors */
    h1, h2, h3, h4, h5, h6, 
    .title, 
    .book-title,
    .price,
    .active-link {
        color: #ffffff !important;
    }

    p, span, .author-name, .subtitle {
        color: #b0b0b0 !important;
    }

    /* Links and Buttons */
    a {
        color: #51a6ed !important; /* Lighter blue for readability */
    }

    .btn-primary, 
    .primary-button, 
    button.buy-button {
        background-color: #0079ad !important; /* Kobo Blue */
        border: none !important;
        color: #fff !important;
    }

    .btn-secondary, 
    .secondary-button {
        background-color: #333 !important;
        color: #fff !important;
        border: 1px solid #555 !important;
    }

    /* Search Bar */
    input[type="text"], 
    input[type="search"],
    .search-input {
        background-color: #2a2a2a !important;
        color: #fff !important;
        border: 1px solid #444 !important;
    }

    /* Product Details Page */
    .item-detail-content, 
    .description-anchor,
    .synopsis-description {
        color: #ccc !important;
    }

    /* Cart and Checkout */
    .order-summary, 
    .cart-item {
        background-color: #1e1e1e !important;
        border-color: #333 !important;
    }

    /* Footer */
    footer, 
    .footer-container {
        background-color: #0f0f0f !important;
        border-top: 1px solid #333 !important;
    }

    /* Fix for bright white images (Optional: lowers brightness of book covers) */
    img.book-cover, 
    .cover-image {
        filter: brightness(0.8) contrast(1.1);
        transition: filter 0.3s ease;
    }

    img.book-cover:hover {
        filter: brightness(1);
    }

    /* Hide specific harsh white dividers */
    hr {
        border-color: #333 !important;
    }
    
    /* Ratings Stars */
    .kobo-rating-stars .filled {
        color: #ffcc00 !important;
    }
}
